import OpenFin from '@openfin/core';

import { WindowName } from '@common/utils/window';

const NON_EXISTENT_PARENT_IDENTITY: OpenFin.Identity = {
    uuid: '__NON_EXISTENT',
    name: '__NON_EXISTENT'
};

const pendingHiddenListenerByWindowKey = new Set<string>();

const shouldResetParentIdentityOnHidden = (parentIdentity: OpenFin.Identity) =>
    parentIdentity.name !== WindowName.EnterpriseBookmarkDialogWindow;

const getWindowKey = (popupWindow: OpenFin.Window) => {
    const { uuid, name } = popupWindow.identity;
    return `${uuid}:${name}`;
};

export const configurePopupParentIdentityLifecycle = async (
    popupWindow: OpenFin.Window,
    parentIdentity: OpenFin.Identity,
    isWindows = true
) => {
    // SAAS-2980 - Windows Limitation:
    // - when showTaskbarIcon: false - the window is visible on all desktops
    // - to prevent this, we set a parentIdentity on the popupWindow
    // - we need to keep it alive after the parent window is closed,
    // so on hidden we set the parentIdentity to a non-existent window identity
    // which in core will unset the parent.
    await popupWindow.updateOptions({
        // @ts-expect-error OpenFin types do not include experimental parentIdentity yet
        experimental: { parentIdentity }
    });

    const popupWindowKey = getWindowKey(popupWindow);

    // don't prepend multiple .once listeners
    if (pendingHiddenListenerByWindowKey.has(popupWindowKey)) {
        return;
    }
    pendingHiddenListenerByWindowKey.add(popupWindowKey);

    const lifeCycleListener = async () => {
        try {
            if (!shouldResetParentIdentityOnHidden(parentIdentity)) {
                return;
            }

            await popupWindow.updateOptions({
                // @ts-expect-error OpenFin types do not include experimental parentIdentity yet
                experimental: { parentIdentity: NON_EXISTENT_PARENT_IDENTITY }
            });
        } finally {
            pendingHiddenListenerByWindowKey.delete(popupWindowKey);
        }
    };

    if (isWindows) {
        await popupWindow.prependOnceListener('hidden', lifeCycleListener);
    } else {
        // On Mac when we dismiss popup windows, we never receive hidden for some reason, but blurred always fires
        await popupWindow.prependOnceListener('blurred', lifeCycleListener);
    }
};

// Test helper: clears module-level listener dedupe state between test cases.
export const resetPopupParentIdentityLifecycleForTests = () => {
    pendingHiddenListenerByWindowKey.clear();
};
