import { FC, useEffect, useState } from 'react';

import styled from 'styled-components';

import { IconSizeType, IconType } from '@openfin/ui-library';

import { createLogger } from '@common/utils/logger';
import { enterpriseCustomIconId } from '@common/utils/test-ids';

const logger = createLogger('enterprise.BrandIcon');

import { CustomIcon } from '@common/components/Icon/CustomIcon';

import { VARS } from '@openfin/theme-engine';

type BrandLogoContainerProps = {
    size: IconSizeType;
    fallbackIcon?: IconType;
};

const Icon = styled(CustomIcon)`
    width: 100%;
    height: 100%;
`;

const BrandIcon: FC<BrandLogoContainerProps> = ({ size, fallbackIcon = 'EnterpriseGlobeIcon' }) => {
    const [iconUrl, setIconUrl] = useState<string>();

    useEffect(() => {
        const updateIcon = () => {
            const raw = getComputedStyle(document.documentElement).getPropertyValue(VARS['icon.symbol']).trim();
            /*
             * theme-engine will sometimes add double quotes to image URLs
             * (see escapeSemicolon function in packages/theme-engine/src/utils/export.ts)
             * We need to remove them so that the Image component that uses this URL loads it properly.
             */
            const url = raw.length >= 2 && raw.startsWith('"') && raw.endsWith('"') ? raw.slice(1, -1) : raw;
            logger.debug('updateIcon', 'Updating icon url', { url });
            setIconUrl(url);
        };

        updateIcon();

        const observer = new MutationObserver((mutations) => {
            for (const mutation of mutations) {
                if (mutation.attributeName === 'data-scheme') {
                    updateIcon();
                }
            }
        });

        observer.observe(document.documentElement, { attributes: true });

        return () => observer.disconnect();
    }, []);

    return (
        <span role="img" aria-label="Company Logo" style={{ display: 'inline-block', width: '100%', height: '100%' }}>
            <Icon size={size} iconURL={iconUrl} testId={enterpriseCustomIconId} fallbackIcon={fallbackIcon} />
        </span>
    );
};

export default BrandIcon;
